export function allow(key: string, now = Date.now()) {
  const b = buckets.get(key) ?? { tokens: CAP, at: now };
  b.tokens = Math.min(CAP, b.tokens + ((now - b.at) / 1000) * REFILL_PER_SEC);
  b.at = now;
  if (b.tokens < 1) return false;
  b.tokens -= 1;
  buckets.set(key, b);
  return true;
}
